fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Compute current separation as a non-negative i32
    let dist = (a - b).abs() as i32;
    // Compute the maximum achievable distance, capped at n-1
    let max_dist = (dist + x as i32).min((n - 1) as i32);
    // Cast back to i8 for the return
    max_dist as i8
}

